package cyrilificate;

import java.util.Scanner;
import cyrilificate.CyrilicTranslator;

public class App {
	public static String AskForMessageToTranslate()
	{
		System.out.println("Welcome cyrilify! \n A silly attempt by me to make a engine That translates latin characters into their closest cyrilic counterparts. \n");
		System.out.print("Please input the string you would like to translate: ");
		
		Scanner input_scanner = new Scanner(System.in);
			
		try {
			String gotline = input_scanner.nextLine();

			input_scanner.close();

			if (gotline.length() <= 0) {
				throw new IllegalArgumentException("Input message was empty, Shutting down program....");
			}

			return gotline;	
		} catch (Exception e) {
			System.out.println(e.getMessage());
			System.exit(1);	
		}

		return null;
	}

	// only allowing ascii characters for now
	public static Boolean CheckIfTranslatable(final String str)
	{
		for (int i = 0; i < str.length(); i++) {
    	if (str.charAt(i) > 127) {
      	return false;
    	}
    }
  	return true;
	}

  public static void main(String[] args) 
	{
		final String latin_original_text = AskForMessageToTranslate();
		
		if (CheckIfTranslatable(latin_original_text) == false) {
			System.out.println("Error: Input message is only allowed to contain ASCII characters. Please change you input...");
			System.exit(1);
		}

		CyrilicTranslator texttranslator = new CyrilicTranslator(latin_original_text.toLowerCase());

		final String cyrilic_encodeded_text = texttranslator.translated_str;

		System.out.print("Your text has been encoded into: ");
		System.out.println(cyrilic_encodeded_text);

		System.exit(0);
  }
}
